const state={data:null,time:233/(30000/1001),frame:233,edits:{},sample:null,selected:'right_wrist',mask:null,viewer:null};
const maskCache=new Map(),ballMaskCache=new Map();
const connections=[['nose','neck'],['neck','left_shoulder'],['neck','right_shoulder'],['left_shoulder','left_elbow'],['left_elbow','left_wrist'],['right_shoulder','right_elbow'],['right_elbow','right_wrist'],['left_shoulder','left_hip'],['right_shoulder','right_hip'],['left_hip','right_hip'],['left_hip','left_knee'],['left_knee','left_ankle'],['right_hip','right_knee'],['right_knee','right_ankle'],['left_ankle','left_big_toe'],['right_ankle','right_big_toe']];
