function nearest(items,time,key='time'){if(!items?.length)return null;let best=items[0];for(const p of items){if(Math.abs(p[key]-time)<Math.abs(best[key]-time))best=p;}return best;}
function point(p){return p?Array.isArray(p)?{x:p[0],y:p[1],confidence:p[2]}:p:null;}
function usable(p){return p&&Number.isFinite(p.x)&&Number.isFinite(p.y)&&p.confidence!==0;}
function jointMap(sample,raw=false){const source=sample?.[raw?'raw2d':'joints2d']||sample?.joints2d||{};return Object.fromEntries(Object.entries(source).map(([n,p])=>[n,point(p)]));}
function getJoints(raw=false){const joints=jointMap(state.sample,raw);if(!raw&&state.edits[state.frame])for(const[n,p]of Object.entries(state.edits[state.frame]))joints[n]=p;return joints;}
export function angle(a,b,c){if(!usable(a)||!usable(b)||!usable(c))return null;return jointAngle(a,b,c);}
function label(ctx,text,x,y,color='#fff',size=15){ctx.font=`${size}px "Courier New",monospace`;ctx.fillStyle=color;ctx.fillText(text,x,y);}
function line(ctx,a,b,color,width=3){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();}
function drawPose(ctx,joints,{selected=null,raw=false}={}){
 ctx.lineCap='round';for(const[a,b]of(state.data?.bones||connections)){if(!usable(joints[a])||!usable(joints[b]))continue;line(ctx,joints[a],joints[b],raw?'#fff8':'#141414',7);line(ctx,joints[a],joints[b],raw?'#ffffff':'#f4f1d9',3);}
 for(const[n,p]of Object.entries(joints)){if(!usable(p)||n.includes('eye')||n.includes('ear')||n.includes('small_toe'))continue;ctx.beginPath();ctx.arc(p.x,p.y,n===selected?10:5,0,Math.PI*2);ctx.fillStyle=n===selected?'#e33425':raw?'#ffffff':'#f7f1d3';ctx.fill();ctx.strokeStyle='#151515';ctx.lineWidth=2;ctx.stroke();if(n===selected){ctx.fillStyle='#151515dd';ctx.fillRect(p.x+15,p.y-30,170,30);label(ctx,n.replace('left_','I / ').replace('right_','D / '),p.x+22,p.y-10,'#fff',15);}}
}
function drawBall(ctx,silhouette=false){if(!$('show-ball').checked)return;const sourceFrame=state.frame+2422,mask=ballMaskCache.get(sourceFrame);if(mask){ctx.save();ctx.globalAlpha=silhouette?1:.72;ctx.drawImage(mask.canvas,mask.crop[0],mask.crop[1]);ctx.restore();if(!silhouette)label(ctx,'BALÓN / SAM 3.1',mask.center[0]+30,mask.center[1]-45,'#fff',14);return;}const b=state.data?.ball?.samples.find(p=>p.sourceFrame===sourceFrame);if(!b||b.x==null||silhouette)return;ctx.strokeStyle='#fff';ctx.lineWidth=3;ctx.setLineDash([7,7]);ctx.beginPath();ctx.arc(b.x,b.y,b.r+5,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);label(ctx,'BALÓN / ANOTACIÓN',b.x+30,b.y-45,'#fff',14);}
function loadBallMasks(){for(const b of state.data?.ballSegmentation?.samples||[]){if(!b.accepted)continue;const img=new Image();img.onload=()=>{const [l,t,r,bot]=b.crop,c=document.createElement('canvas');c.width=r-l;c.height=bot-t;const x=c.getContext('2d',{willReadFrequently:true});x.drawImage(img,l,t,r-l,bot-t,0,0,r-l,bot-t);const d=x.getImageData(0,0,c.width,c.height);for(let i=0;i<d.data.length;i+=4){const a=d.data[i];d.data[i]=228;d.data[i+1]=52;d.data[i+2]=30;d.data[i+3]=a;}x.putImageData(d,0,0);ballMaskCache.set(b.sourceFrame,{canvas:c,crop:b.crop,center:b.centroid});if(state.frame+2422===b.sourceFrame)draw();};img.src=b.mask.startsWith('/')?b.mask:'/assets/'+b.mask;}}

function blank(ctx,text){ctx.fillStyle='#fafaf7';ctx.fillRect(0,0,1280,720);label(ctx,text,45,360,'#8a8a84',18);}
function baseImage(ctx){if(video.readyState>=2){ctx.drawImage(video,0,0,1280,720);return true;}blank(ctx,'CARGANDO FOTOGRAMA');return false;}
function requestMask(sample,prefetch=false){if(!sample?.mask){if(!prefetch)state.mask=null;return;}const key=sample.mask;if(maskCache.has(key)){if(!prefetch)state.mask=maskCache.get(key);return;}if(!prefetch)state.mask=null;const img=new Image();maskCache.set(key,null);img.onload=()=>{const c=document.createElement('canvas');c.width=1280;c.height=720;const x=c.getContext('2d',{willReadFrequently:true});x.drawImage(img,0,0,1280,720);const d=x.getImageData(0,0,1280,720);for(let i=0;i<d.data.length;i+=4){const a=d.data[i];d.data[i]=203;d.data[i+1]=34;d.data[i+2]=27;d.data[i+3]=a;}x.putImageData(d,0,0);const black=document.createElement('canvas');black.width=1280;black.height=720;const bx=black.getContext('2d');bx.drawImage(c,0,0);bx.globalCompositeOperation='source-in';bx.fillStyle='#151515';bx.fillRect(0,0,1280,720);const pack={color:c,black};maskCache.set(key,pack);if(state.sample?.mask===key){state.mask=pack;draw();}if(maskCache.size>9){const oldest=maskCache.keys().next().value;maskCache.delete(oldest);}};img.onerror=()=>{maskCache.set(key,false);};img.src=key.startsWith('/')?key:'/assets/'+key;}
function draw(){
 const j=getJoints();const seg=contexts['segment-canvas'];if(baseImage(seg)&&state.mask){seg.save();seg.globalAlpha=.42;seg.drawImage(state.mask.color,0,0);seg.restore();}drawBall(seg);
 const mc=contexts['mask-canvas'];mc.fillStyle='#fff';mc.fillRect(0,0,1280,720);if(state.mask){mc.drawImage(state.mask.black,0,0);}else label(mc,state.sample?.valid===false?'SIN SILUETA FIABLE EN ESTA MUESTRA':'MÁSCARA NO DISPONIBLE',55,360,'#8a8a84',18);drawBall(mc,true);
 const pc=contexts['pose-canvas'];baseImage(pc);if(state.sample?.valid){pc.fillStyle='#0002';pc.fillRect(0,0,1280,720);drawPose(pc,j);drawBall(pc);}else label(pc,'JUGADOR NO LOCALIZADO / SIN POSE',35,675,'#fff',18);
 const ed=contexts.editor;baseImage(ed);if(state.sample?.valid)drawPose(ed,getJoints($('raw-pose').checked),{selected:state.selected,raw:$('raw-pose').checked});
 const knee=angle(j.left_hip,j.left_knee,j.left_ankle),hip=angle(j.left_shoulder,j.left_hip,j.left_knee);$('knee-angle').textContent=knee==null?'—':`${knee.toFixed(1)}°`;$('hip-angle').textContent=hip==null?'—':`${hip.toFixed(1)}°`;
 const k3=state.viewer?.getKneeAngle()??null;$('knee-3d').textContent=k3==null?'—':`${k3.toFixed(1)}°`;const ankle=state.viewer?.getAnkleElevation()??null;$('ankle-direction').textContent=ankle==null?'—':`${ankle.toFixed(1)}°`;
 const p=($('raw-pose').checked?getJoints(true):j)[state.selected];$('point-x').textContent=usable(p)?p.x.toFixed(1):'—';$('point-y').textContent=usable(p)?p.y.toFixed(1):'—';
 $('pose-quality').textContent=state.sample?.valid?`MUESTRA ${Number(state.sample.time).toFixed(3)} s / POSE ESTIMADA`:'SIN OBSERVACIÓN FIABLE';
 if(state.sample)$('seg-status').textContent=`MÁSCARA ${Number(state.sample.time).toFixed(3)} s · VIDEO ${state.time.toFixed(3)} s`;
 drawAngleChart();drawBallChart();
}
function sync(mediaTime){const t=typeof mediaTime==='number'?mediaTime:video.currentTime;state.frame=Math.max(0,Math.min(341,Math.floor(t*fps+.001)));state.time=state.frame/fps;$('timeline').value=state.frame;$('time').textContent=`${state.time.toFixed(2).padStart(5,'0')} s`;$('frame').textContent=`F ${String(state.frame).padStart(4,'0')} / 0341`;if(state.data){const s=state.data.frames[state.frame];if(s!==state.sample){state.sample=s;requestMask(s);for(let k=1;k<=3;k++)requestMask(state.data.frames[state.frame+k],true);}state.viewer?.setTime(state.time);}draw();}
function setTime(time){video.pause();video.currentTime=Math.max(0,Math.min(duration-1/fps,time));}
function toggle(){if(video.paused){if(video.currentTime>=duration-0.1)video.currentTime=0;video.play().catch(()=>{$('hero-play').hidden=false;});}else video.pause();}
function updatePlay(){const paused=video.paused;$('play').innerHTML=paused?'▶ <span>REPRODUCIR</span>':'Ⅱ <span>PAUSAR</span>';$('hero-play').hidden=!paused;for(const b of document.querySelectorAll('.play-linked'))b.textContent=paused?'▶ REPRODUCIR SECUENCIA':'Ⅱ PAUSAR SECUENCIA';}
video.addEventListener('loadedmetadata',()=>{video.currentTime=state.time;});video.addEventListener('seeked',sync);video.addEventListener('play',updatePlay);video.addEventListener('pause',updatePlay);video.addEventListener('ended',updatePlay);video.addEventListener('error',()=>{$('load-error').hidden=false;});
let lastTime=-1;if('requestVideoFrameCallback' in video){const onFrame=(_,meta)=>{sync(meta.mediaTime);video.requestVideoFrameCallback(onFrame);};video.requestVideoFrameCallback(onFrame);}else{function tick(){if(video.readyState>=2&&video.currentTime!==lastTime){lastTime=video.currentTime;sync();}requestAnimationFrame(tick);}requestAnimationFrame(tick);}
$('play').onclick=toggle;$('hero-play').onclick=toggle;document.querySelectorAll('.play-linked').forEach(b=>b.onclick=toggle);$('prev').onclick=()=>setTime((state.frame-1)/fps);$('next').onclick=()=>setTime((state.frame+1)/fps);$('timeline').oninput=e=>setTime(Number(e.target.value)/fps);$('speed').onchange=e=>video.playbackRate=Number(e.target.value);$('show-ball').onchange=()=>{state.viewer?.setTime(state.time);draw();};$('raw-pose').onchange=()=>{video.pause();draw();};$('joint').onchange=e=>{state.selected=e.target.value;draw();};$('go-contact').onclick=()=>setTime(state.data?.ball?.contact?.estimatedClipTime||8.008);
function editPoint(x,y){if(!state.sample?.valid)return;$('raw-pose').checked=false;video.pause();const p={x:Math.max(0,Math.min(1280,x)),y:Math.max(0,Math.min(720,y)),confidence:null,manuallyEdited:true};state.edits[state.frame]??={};state.edits[state.frame][state.selected]=p;$('edit-status').textContent=`${Object.values(state.edits).reduce((n,f)=>n+Object.keys(f).length,0)} AJUSTES / ${Object.keys(state.edits).length} FOTOGRAMAS`;draw();}
const editor=$('editor');let dragging=false;function eventPoint(e){const r=editor.getBoundingClientRect();return{x:(e.clientX-r.left)*1280/r.width,y:(e.clientY-r.top)*720/r.height};}
editor.addEventListener('pointerdown',e=>{if(!state.sample?.valid)return;const p=eventPoint(e),j=getJoints($('raw-pose').checked);let n=state.selected,d=35;for(const[k,q]of Object.entries(j)){if(!usable(q)||!Array.from($('joint').options).some(o=>o.value===k))continue;const nd=Math.hypot(p.x-q.x,p.y-q.y);if(nd<d){n=k;d=nd;}}state.selected=n;$('joint').value=n;dragging=true;editor.setPointerCapture(e.pointerId);editor.focus({preventScroll:true});editPoint(p.x,p.y);});editor.addEventListener('pointermove',e=>{if(dragging){const p=eventPoint(e);editPoint(p.x,p.y);}});editor.addEventListener('pointerup',()=>dragging=false);editor.addEventListener('pointercancel',()=>dragging=false);editor.addEventListener('keydown',e=>{const moves={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]},m=moves[e.key],p=getJoints($('raw-pose').checked)[state.selected];if(m&&usable(p)){e.preventDefault();const step=e.shiftKey?10:1;editPoint(p.x+m[0]*step,p.y+m[1]*step);}});
$('reset-frame').onclick=()=>{delete state.edits[state.frame];$('edit-status').textContent=`${Object.values(state.edits).reduce((n,f)=>n+Object.keys(f).length,0)} AJUSTES EN ESTA SESIÓN`;draw();};$('export-edits').onclick=()=>{const output={schema:'atlas-session-corrections-v1',source:state.data?.metadata?.source,sourceStartFrame:2422,sourceStart:2422/fps,fps,coordinateSpace:{width:1280,height:720,origin:'top-left'},baseAnalysis:'/assets/analysis.json',frames:Object.entries(state.edits).map(([f,j])=>({clipFrame:Number(f),sourceFrame:Number(f)+2422,sourceTime:(Number(f)+2422)/fps,clipTime:Number(f)/fps,joints2d:j})),note:'Manual session corrections affect 2D frame annotations only. Blender animation is not recalculated.'};const url=URL.createObjectURL(new Blob([JSON.stringify(output,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='atlas-correcciones.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
function drawAngleChart(){const c=$('angle-chart'),x=c.getContext('2d'),w=c.width,h=c.height;x.clearRect(0,0,w,h);const left=45,right=w-22,top=24,bottom=h-35,px=t=>left+t/duration*(right-left),py=a=>bottom-a/180*(bottom-top);for(const a of[0,90,180]){line(x,{x:left,y:py(a)},{x:right,y:py(a)},'#e0e0db',1);label(x,String(a)+'°',0,py(a)+4,'#888',12);}for(const t of[0,2,4,6,8,10])label(x,t+'s',px(t)-5,h-7,'#888',12);let prev=null;for(const s of state.data?.frames||[]){const j=jointMap(s);Object.assign(j,state.edits[s.clipFrame]||{});const a=angle(j.left_hip,j.left_knee,j.left_ankle);if(a==null||!s.valid){prev=null;continue;}const p={x:px(s.time),y:py(a)};if(prev&&s.time-prev.time<.25)line(x,prev,p,'#222',2);prev={...p,time:s.time};}line(x,{x:px(state.time),y:top},{x:px(state.time),y:bottom},'#c8241a',2);const contact=state.data?.ball?.contact?.estimatedClipTime;if(contact){x.setLineDash([3,5]);line(x,{x:px(contact),y:top},{x:px(contact),y:bottom},'#b4b4ad',1);x.setLineDash([]);label(x,'CONTACTO',px(contact)+7,18,'#888',10);}}
function drawBallChart(){const c=$('ball-chart'),x=c.getContext('2d'),w=c.width,h=c.height;x.clearRect(0,0,w,h);const samples=state.data?.ball?.samples||[],visible=samples.filter(s=>s.x!=null),px=v=>45+v/900*(w-90),py=v=>45+(v-280)/360*(h-90);for(const y of[300,400,500,600]){line(x,{x:45,y:py(y)},{x:w-45,y:py(y)},'#e4e4dd',1);label(x,String(y),0,py(y)+4,'#888',12);}for(const val of[0,200,400,600,800])label(x,String(val),px(val)-10,h-10,'#888',12);label(x,'X / px',w-80,h-10,'#888',12);label(x,'Y / px',0,18,'#888',12);let prev=null;for(const s of samples){if(s.x==null){prev=null;continue;}const p={x:px(s.x),y:py(s.y)};if(prev)line(x,prev,p,s.clipTime>=8.02?'#c8241a':'#aaa',2);x.beginPath();x.arc(p.x,p.y,s.quality==='low'?4:5,0,Math.PI*2);x.fillStyle=s.clipTime>=8.02?'#c8241a':'#aaa';x.fill();prev=p;}const now=nearest(samples,state.time,'clipTime');if(now?.x!=null&&Math.abs(now.clipTime-state.time)<.06){x.beginPath();x.arc(px(now.x),py(now.y),13,0,Math.PI*2);x.strokeStyle='#151515';x.lineWidth=2;x.stroke();}const after=visible.filter(s=>s.clipTime>8.03&&s.quality!=='low');if(after.length>=2){const a=after[0],b=after[1],theta=projectedBallAngle(a,b);$('ball-angle').textContent=theta.toFixed(1)+'°';label(x,`SALIDA / ${a.clipTime.toFixed(3)}–${b.clipTime.toFixed(3)} s`,45,25,'#c8241a',13);}label(x,'TRAYECTORIA EN IMAGEN · INCLUYE MOVIMIENTO DE CÁMARA',45,h-32,'#777',11);}
function setupNavigation(){const navLinks=[...document.querySelectorAll('.chapters a')];const obs=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){navLinks.forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id));}},{rootMargin:'-15% 0px -65% 0px',threshold:0});document.querySelectorAll('.chapter').forEach(s=>obs.observe(s));const transport=$('transport'),spacer=document.createElement('div');spacer.className='transport-spacer';transport.before(spacer);const anchor=document.createElement('div');transport.before(anchor);let floated=false;window.addEventListener('scroll',()=>{const should=anchor.getBoundingClientRect().top<66;if(should!==floated){floated=should;transport.classList.toggle('floating-transport',should);spacer.classList.toggle('shown',should);}},{passive:true});}
