async function init(){try{const res=await fetch('/assets/analysis.json');if(!res.ok)throw Error('Analysis missing');state.data=await res.json();if(!Array.isArray(state.data.frames))throw Error('Analysis invalid');loadBallMasks();$('mask-method').textContent=state.data.metadata.segmentationLabel||'SAM 3.1 / INFERENCIA INDEPENDIENTE POR FOTOGRAMA';$('pipeline-description').textContent=state.data.metadata.pipelineDescription||$('pipeline-description').textContent;$('review-description').textContent=state.data.metadata.reviewDescription||$('review-description').textContent;const hero=state.data.metadata.hero;if(hero)$('hero-cutout').src=hero;const cinematic=state.data.metadata.cinematic;if(cinematic){$('cinematic').src=cinematic;$('download-film').href=cinematic;}const poster=state.data.metadata.renderPoster;if(poster){$('cinematic').poster=poster;document.querySelector('.viewer-fallback').src=poster;}if(state.data.metadata.cinematicPoster)$('cinematic').poster=state.data.metadata.cinematicPoster;if(video.readyState>=1)sync();else draw();state.viewer=await initBodyViewer($('viewer'),state);draw();$('vectors').onchange=()=>state.viewer?.setVectors($('vectors').checked);$('bones').onchange=()=>state.viewer?.setBones($('bones').checked);$('full-rig').onchange=()=>state.viewer?.setFullRig($('full-rig').checked);document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('selected',x===b));state.viewer?.setView(b.dataset.view);});registerWebMCP();}catch(e){console.error('Atlas analysis',e);$('load-error').hidden=false;$('viewer-status').textContent='VISUALIZADOR NO DISPONIBLE · CONSULTA LA PELÍCULA';}}
function registerWebMCP(){if(!document.modelContext?.registerTool)return;const life=new AbortController();window.addEventListener('pagehide',()=>life.abort(),{once:true});const regs=[{name:'atlas_seek_frame',title:'Seleccionar un fotograma',description:'Detiene la repetición y sincroniza las vistas con un fotograma entre 0 y 341.',inputSchema:{type:'object',properties:{frame:{type:'integer',minimum:0,maximum:341}},required:['frame'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!Number.isInteger(input?.frame)||input.frame<0||input.frame>341)throw Error('frame must be an integer 0–341');setTime(input.frame/fps);await new Promise(resolve=>{if(!video.seeking)resolve();else video.addEventListener('seeked',resolve,{once:true});});return{frame:state.frame,time:state.time,sampleTime:state.sample?.time};}},{name:'atlas_read_observation',title:'Leer la observación actual',description:'Devuelve coordenadas articulares, muestra de origen y límites del fotograma actual.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({frame:state.frame,clipTime:state.time,sampleTime:state.sample?.time,joints2d:getJoints(),limitations:state.data.metadata.limitations})}];for(const tool of regs)try{Promise.resolve(document.modelContext.registerTool(tool,{signal:life.signal})).catch(()=>{});}catch{}}
